#define USB3_OTGCMD_DEV_BUS_REQ(x)               (((uint32_t)(((uint32_t)(x)) << USB3_OTGCMD_DEV_BUS_REQ_SHIFT)) & USB3_OTGCMD_DEV_BUS_REQ_MASK)

