/*! SS_HOST_DISABLED_CLR - Enable SuperSpeed host functionality */
#define USB3_OTGCMD_SS_HOST_DISABLED_CLR(x)      (((uint32_t)(((uint32_t)(x)) << USB3_OTGCMD_SS_HOST_DISABLED_CLR_SHIFT)) & USB3_OTGCMD_SS_HOST_DISABLED_CLR_MASK)

