#define USB3_OTGCMD_A_SET_B_HNP_EN_SET(x)        (((uint32_t)(((uint32_t)(x)) << USB3_OTGCMD_A_SET_B_HNP_EN_SET_SHIFT)) & USB3_OTGCMD_A_SET_B_HNP_EN_SET_MASK)

#define USB3_OTGCMD_A_SET_B_HNP_EN_CLR_MASK      (0x1000000U)
