#define USB3_OTGCMD_B_HNP_EN_SET_MASK            (0x2000000U)
#define USB3_OTGCMD_B_HNP_EN_SET_SHIFT           (25U)
/*! B_HNP_EN_SET - This bit should be written if SetFeature(b_hnp_enable) has been accepted */
