#define USB3_OTGSTS_OTG_MODE_MASK                (0x40U)
#define USB3_OTGSTS_OTG_MODE_SHIFT               (6U)
/*! OTG_MODE - OTG mode: 0 - A-Device 1 - B-Device Valid only if OTG_IS_ENABLED is 1 */
