#define USB3_XECP_DCERSTBA_HIGH_ERSTBA_H(x)      (((uint32_t)(((uint32_t)(x)) << USB3_XECP_DCERSTBA_HIGH_ERSTBA_H_SHIFT)) & USB3_XECP_DCERSTBA_HIGH_ERSTBA_H_MASK)
