#define USB3_XECP_DCERDP_LOW_Deq_Ptr_L(x)        (((uint32_t)(((uint32_t)(x)) << USB3_XECP_DCERDP_LOW_Deq_Ptr_L_SHIFT)) & USB3_XECP_DCERDP_LOW_Deq_Ptr_L_MASK)
