#define USB3_USB_CONF_DSING(x)                   (((uint32_t)(((uint32_t)(x)) << USB3_USB_CONF_DSING_SHIFT)) & USB3_USB_CONF_DSING_MASK)

#define USB3_USB_CONF_DMULT_MASK                 (0x200U)
