#define USB3_USB_CONF_CLK2OFFDS(x)               (((uint32_t)(((uint32_t)(x)) << USB3_USB_CONF_CLK2OFFDS_SHIFT)) & USB3_USB_CONF_CLK2OFFDS_MASK)

